using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static class MeetingBuild {
 static string Out=>Path.GetFullPath("../../../outputs/PreMeetingDemo");
 public static void Build(){
 EditorSceneManager.OpenScene("Assets/Stage08D2/Scenes/Stage08D2_Rover_Fidelity_Evaluation.unity");Directory.CreateDirectory("Assets/PreMeeting/Materials");
 var root=GameObject.Find("Stage08D2 Repaired Robotic Rover");if(!root)throw new Exception("Rover absent");int slots=0;
 foreach(var r in root.GetComponentsInChildren<Renderer>()){var a=r.sharedMaterials;for(int i=0;i<a.Length;i++)if(new[]{"glass_trans","glass lens","glass_2"}.Any(n=>a[i].name==n||a[i].name==n.Replace(" ","_"))) {var path="Assets/PreMeeting/Materials/"+a[i].name.Replace(" ","_")+"_Transparent.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(a[i]);m.name=a[i].name+" transparent approximation";var c=m.GetColor("_BaseColor");c.a=.28f;m.SetColor("_BaseColor",c);m.SetFloat("_Surface",1);m.SetFloat("_Blend",0);m.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);m.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);m.SetFloat("_ZWrite",0);m.SetOverrideTag("RenderType","Transparent");m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.renderQueue=3000;AssetDatabase.CreateAsset(m,path);}a[i]=m;slots++;}r.sharedMaterials=a;}
 if(slots==0)throw new Exception("No glass mapped; inspect names");
 var g=new GameObject("Meeting graphics controls — isolated preview only").AddComponent<MeetingGraphics>();g.source=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/Mobile_RPAsset.asset");
 var dust=new GameObject("Restrained dust — synthetic Mars atmosphere").AddComponent<ParticleSystem>();var main=dust.main;main.maxParticles=100;main.startLifetime=8;main.startSize=.05f;main.startSpeed=.2f;main.startColor=new Color(.6f,.45f,.3f,.2f);var shape=dust.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(20,3,20);dust.transform.position=Vector3.up*1.5f;var mat=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));AssetDatabase.CreateAsset(mat,"Assets/PreMeeting/Materials/Dust_v2.mat");dust.GetComponent<ParticleSystemRenderer>().sharedMaterial=mat;
 var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();string target="Assets/PreMeeting/PreMeeting_Mars_Visual_Preview_v2.unity";if(File.Exists(target))throw new Exception("Refuse scene overwrite");EditorSceneManager.SaveScene(scene,target);AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(target);
 var cam=UnityEngine.Object.FindFirstObjectByType<Camera>();string[] names={"Low","Balanced","High","Ultra Preview"};var settings=UnityEngine.Object.FindFirstObjectByType<MeetingGraphics>();settings.InitializeForValidation();
 var lines=new System.Collections.Generic.List<string>();for(int i=0;i<4;i++){settings.Apply(i);var p=(UniversalRenderPipelineAsset)QualitySettings.renderPipeline;lines.Add($"{names[i]} scale={p.renderScale} shadows={p.mainLightShadowmapResolution} distance={p.shadowDistance} MSAA={p.msaaSampleCount} mips={QualitySettings.globalTextureMipmapLimit} LOD={QualitySettings.lodBias} cap={Application.targetFrameRate}");var rt=new RenderTexture(1280,800,24);cam.targetTexture=rt;for(int j=0;j<3;j++)cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1280,800,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,800),0,0);tex.Apply();File.WriteAllBytes(Out+"/Screenshots/Preview_"+i+".png",tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}
 lines.Add("Glass material slots mapped="+slots);lines.Add("Save/reload PASS; batch Editor camera renders, not gameplay/FPS evidence");File.WriteAllLines(Out+"/Graphics_Validation.txt",lines);Debug.Log("MEETING_BUILD_PASS"); }
}
